import React, { useState } from 'react';
import { IntlProvider } from 'react-intl';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import ColourSwatches from './index';
import type { ColourVariant } from './index';

// The icons barrel (overrides/app/components/icons/index.tsx) re-exports the SFCC icons barrel,
// which has a top-level side effect that fails under Vitest (SVG imports resolve to path strings,
// not components). Mock it at the barrel level per testing.md > "Known gap: ZimmIcon throws under Vitest".
vi.mock('../../icons', () => ({
  ChevronLeftIcon: () => null,
  ChevronRightIcon: () => null,
}));

/*
 * Deliberately NOT a re-test of what the Storybook `play` functions already cover (click moves
 * selection, label follows). Per .claude/rules/testing.md, coverage is not duplicated across
 * layers — this file targets the logic edges a story cannot cheaply enumerate:
 *
 *   - the `currentIndex === -1` backward case, where plain modulo silently lands on the
 *     second-to-last swatch instead of the last (the component carries a comment warning
 *     about exactly this — it is the kind of bug that survives a refactor invisibly)
 *   - wrap boundaries in both directions
 *   - the DIS query-string separator, which must be `&` when the resolved link already has `?`
 *   - the roving-tabIndex invariant: exactly one tab stop, always
 *
 * It is also the only layer that runs locally: `test-storybook` currently fails on every story
 * in the repo (pre-existing `StorybookTestRunnerError` env fault), so the `play` functions are
 * unverified until CI. These tests are not blocked on that.
 */

const IMG = 'https://example.test/swatch.jpg';

const variant = (value: string, name: string, over: Partial<ColourVariant> = {}): ColourVariant => ({
  value,
  name,
  imageUrl: IMG,
  orderable: true,
  ...over,
});

