const Harness = ({ variants, initial }: { variants: readonly ColourVariant[]; initial?: string }) => {
  const [selected, setSelected] = useState<string | undefined>(initial);
  return (
    <IntlProvider locale="en" defaultLocale="en">
      <ColourSwatches variants={variants} selectedValue={selected} onSelect={setSelected} />
    </IntlProvider>
  );
};

const THREE = [variant('a', 'Alpha'), variant('b', 'Bravo'), variant('c', 'Charlie')];

const radios = () => screen.getAllByRole('radio');
const group = () => screen.getByRole('radiogroup', { name: 'Colour' });

describe('ColourSwatches — AC5 filter', () => {
  test('withholds a colour with no swatch image', () => {
    render(<Harness variants={[...THREE, variant('d', 'Delta', { imageUrl: undefined })]} initial="a" />);

    expect(radios()).toHaveLength(3);
    expect(screen.queryByRole('radio', { name: 'Delta' })).not.toBeInTheDocument();
  });

  test('withholds a colour that is not orderable even when it has a good image', () => {
    // The load-bearing half: an unorderable colour with a perfectly valid image must still
    // be absent. A filter on imageUrl alone would let this one through.
    render(<Harness variants={[...THREE, variant('d', 'Delta', { orderable: false })]} initial="a" />);

    expect(radios()).toHaveLength(3);
    expect(screen.queryByRole('radio', { name: 'Delta' })).not.toBeInTheDocument();
  });

  test('renders nothing selectable when every colour is withheld', () => {
    render(
      <Harness
        variants={[variant('a', 'Alpha', { orderable: false }), variant('b', 'Bravo', { imageUrl: undefined })]}
      />,
    );

    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });
});

describe('ColourSwatches — AC1 single offered colour', () => {
  test('shows the label and colour name but no swatch row', () => {
    render(<Harness variants={[variant('a', 'Alpha')]} />);

