describe('ColourSwatches — ARIA set size across pagination', () => {
  // Regression guard: a screen reader announces radio position/count ("1 of 7") from
  // aria-posinset/aria-setsize when present, falling back to counting DOM siblings when
  // absent. Pagination only ever renders one page's worth of radios into the DOM, so without
  // these attributes VoiceOver reports "1 of 4" (the page size) instead of "1 of 7" (the true
  // count of offered colours) — the exact bug this guards against.
  test('exposes the true total via aria-setsize on the first page, not just the page count', () => {
    render(<Harness variants={SEVEN} initial="a" />);

    const pageOneRadios = radios();
    expect(pageOneRadios).toHaveLength(4);
    pageOneRadios.forEach((radio) => expect(radio).toHaveAttribute('aria-setsize', '7'));
    expect(pageOneRadios.map((r) => r.getAttribute('aria-posinset'))).toEqual(['1', '2', '3', '4']);
  });

  test('continues posinset numbering on the second page, keeping setsize constant', async () => {
    const user = userEvent.setup();
    render(<Harness variants={SEVEN} initial="a" />);

    await user.click(screen.getByRole('button', { name: 'Next colours' }));

    const pageTwoRadios = radios();
    expect(pageTwoRadios).toHaveLength(3);
    pageTwoRadios.forEach((radio) => expect(radio).toHaveAttribute('aria-setsize', '7'));
    expect(pageTwoRadios.map((r) => r.getAttribute('aria-posinset'))).toEqual(['5', '6', '7']);
  });
});

